proof:
by { induction n with
  | zero => simp [pow2]
  | succ n ih => simp [pow2, ih]; exact Nat.succ_pos _ }

by { induction n with
  | zero => simp [pow2]; ring
  | succ n ih => simp [pow2]; exact Nat.le_add_left 1 (pow2 n) }

by { induction n with
  | zero => simp [pow2]; trivial
  | succ n ih => simp [pow2]; exact Nat.le_add_of_le_left ih }
